input.content:
package payflow

import (
	"bytes"
	"encoding/json"
	"fmt"
	"math/big"
	"sort"
)

// 离线流水对账：把外部支付渠道（或任何外部系统）提供的有序流水与本地账本
// 逐笔核对。流水与账本互不修改——对账是只读操作，不改变余额、历史或账本文件。
//
// 报告四种子结果（保持输入顺序）：
//   - matched：编号命中一条成功记录，且全部核对字段一致；
//   - field_mismatch：编号命中成功记录，但至少一个字段不同（列出每个差异）；
//   - missing_in_ledger：账本中没有该编号的成功记录；
//   - duplicate：同一(kind,id)在输入中出现多次，整组全部标为重复，
//     不再判断字段差异，也不再把对应账本记录列为缺失。
//
// 只核对成功记录：已退款的付款仍按原扣款核对，退款单独核对。
// 账本中没有任何对应流水的成功记录另列 missing（先付款后退款，各按成功顺序）。

const (
	ReconMatched         = "matched"
	ReconFieldMismatch   = "field_mismatch"
	ReconMissingInLedger = "missing_in_ledger"
	ReconDuplicate       = "duplicate"
)

// amountJSON 是必须提供、且落在 int64 范围内的整数金额。
// 使用指针 + 自定义解码区分“缺省/null/非数字/越界”等情形。
type amountJSON struct {
	v     int64
	valid bool
}

func (a *amountJSON) UnmarshalJSON(data []byte) error {
	dec := json.NewDecoder(bytes.NewReader(data))
	var v int64
	if err := dec.Decode(&v); err != nil {
		return err
	}
	// 数字字面量之后不允许尾随内容。
	if tok, err := dec.Token(); err != nil {
		return err
	} else {
		_ = tok
		return fmt.Errorf("unexpected trailing content in amount")
	}
}

// flowEntryJSON 是流水的严格解码形态：未知字段拒绝、金额必须存在且为 int64。
type flowEntryJSON struct {
	Kind         string      `json:"kind"`
	ID           string      `json:"id"`
	Account      string      `json:"account"`
	Asset        string      `json:"asset"`
	Amount       *amountJSON `json:"amount"`
	Fee          *amountJSON `json:"fee"`
	Charged      *amountJSON `json:"charged"`
	SettlementID string      `json:"settlement_id"`
}

// flowRequestJSON 仅用于拒绝顶层未知字段。
type flowRequestJSON struct {
	Entries []flowEntryJSON `json:"entries"`
}

// FlowEntry 是校验通过后的一条流水。
type FlowEntry struct {
	Index        int // 从 0 开始的输入位置
	Kind         string
	ID           string
	Account      string
	Asset        string
	Amount       int64
	Fee          int64
	Charged      int64
	SettlementID string // 仅退款有意义
}

// FieldDiff 是一个不同字段：账本值与流水值逐字并列。
type FieldDiff struct {
	Field  string `json:"field"`
	Ledger string `json:"ledger"`
	Flow   string `json:"flow"`
}

// ReconResult 是一条输入流水的核对结果，顺序与输入一致。
type ReconResult struct {
	Index        int         `json:"index"`
	Kind         string      `json:"kind"`
	ID           string      `json:"id"`
	Status       string      `json:"status"`
	SettlementID string      `json:"settlement_id,omitempty"` // 退款：原付款编号
	RefundID     string      `json:"refund_id,omitempty"`     // 付款被退款时：退款编号
	Diffs        []FieldDiff `json:"diffs,omitempty"`
}

// ReconRecordRef 指向一条账本成功记录，并携带其关联记录（付款的退款 /
// 退款的原付款及退款自身），使每个可定位到账本的结果都可追溯。
type ReconRecordRef struct {
	Kind         string `json:"kind"`
	ID           string `json:"id"`
	Account      string `json:"account"`
	Asset        string `json:"asset"`
	Amount       int64  `json:"amount"`
	Fee          int64  `json:"fee"`
	Charged      int64  `json:"charged"`
	Seq          int64  `json:"seq"`
	SettlementID string `json:"settlement_id,omitempty"` // 退款记录：原付款编号
	RefundID     string `json:"refund_id,omitempty"`     // 结算已被退款时：退款编号
	RefundSeq    int64  `json:"refund_seq,omitempty"`
}

// ReconTotalRow 是一个 (账户, 资产) 组合的金额汇总。金额使用十进制整数字符串，
// 累计可以超过 int64 仍保持精确；不同资产各自一行，不相加、不抵消。
type ReconTotalRow struct {
	Account       string `json:"account"`
	Asset         string `json:"asset"`
	ChargedTotal  string `json:"charged_total"`
	RefundedTotal string `json:"refunded_total"`
	NetCharged    string `json:"net_charged"`
}

// ReconTotals 是账本侧与流水侧各自的汇总。
type ReconTotals struct {
	Ledger []ReconTotalRow `json:"ledger"`
	Flow   []ReconTotalRow `json:"flow"`
}

// ReconReport 是一次对账的完整报告。
type ReconReport struct {
	Results         []ReconResult   `json:"results"`
	MissingPayments []ReconRecordRef `json:"missing_payments"`
	MissingRefunds  []ReconRecordRef `json:"missing_refunds"`
	Totals          ReconTotals     `json:"totals"`
	NetDiff         []ReconTotalRow `json:"net_diff"` // 流水净扣款 - 账本净扣款
	MaxPaymentSeq   int64           `json:"max_payment_seq"`
	MaxRefundSeq    int64           `json:"max_refund_seq"`
}

// ParseReconcileRequest 严格解析对账输入。
// 字段缺失、类型不符、未知 kind、数值越界或非法 JSON 均返回 invalid_parameter。
func ParseReconcileRequest(raw []byte) ([]FlowEntry, error) {
	dec := json.NewDecoder(bytes.NewReader(raw))
	var req flowRequestJSON
	if err := dec.Decode(&req); err != nil {
		return nil, ledgerError(ErrInvalid, "parse reconcile JSON: %v", err)
	}
	if tok, err := dec.Token(); err != nil {
		if err.Error() != "EOF" {
			return nil, ledgerError(ErrInvalid, "reconcile: %v", err)
		}
	} else {
		return nil, ledgerError(ErrInvalid, "reconcile: unexpected trailing content after JSON document (token %v)", tok)
	}

	entries := make([]FlowEntry, 0, len(req.Entries))
	for i, e := range req.Entries {
		at := func(msg string, args ...any) error {
			return ledgerError(ErrInvalid, "reconcile entry %d: %s", i, fmt.Sprintf(msg, args...))
		}
		if e.Kind != "payment" && e.Kind != "refund" {
			return nil, at("unknown kind %q (want payment or refund)", e.Kind)
		}
		if e.ID == "" {
			return nil, at("id must not be empty")
		}
		if e.Account == "" {
			return nil, at("account must not be empty")
		}
		if e.Asset == "" {
			return nil, at("asset must not be empty")
		}
		if e.Amount == nil {
			return nil, at("amount is required")
		}
		if e.Fee == nil {
			return nil, at("fee is required")
		}
		if e.Charged == nil {
			return nil, at("charged is required")
		}
		if e.Amount.v <= 0 {
			return nil, at("amount must be a positive int64")
		}
		if e.Fee.v < 0 {
			return nil, at("fee must be a non-negative int64")
		}
		if e.Charged.v <= 0 {
			return nil, at("charged must be a positive int64")
		}
		if e.Kind == "refund" && e.SettlementID == "" {
			return nil, at("settlement_id must not be empty for a refund")
		}
		entries = append(entries, FlowEntry{
			Index:        i,
			Kind:         e.Kind,
			ID:           e.ID,
			Account:      e.Account,
			Asset:        e.Asset,
			Amount:       e.Amount.v,
			Fee:          e.Fee.v,
			Charged:      e.Charged.v,
			SettlementID: e.SettlementID,
		})
	}
	return entries, nil
}

// reconSide 累计单侧（账本或流水）的金额。
type reconSide struct {
	charged  map[balanceKey]*big.Int
	refunded map[balanceKey]*big.Int
}

func newReconSide() reconSide {
	return reconSide{charged: map[balanceKey]*big.Int{}, refunded: map[balanceKey]*big.Int{}}
}

func (s *reconSide) addCharged(k balanceKey, v int64) {
	x := s.charged[k]
	if x == nil {
		x = new(big.Int)
		s.charged[k] = x
	}
	x.Add(x, big.NewInt(v))
}

func (s *reconSide) addRefund(k balanceKey, v int64) {
	x := s.refunded[k]
	if x == nil {
		x = new(big.Int)
		s.refunded[k] = x
	}
	x.Add(x, big.NewInt(v))
}

// ReconcileFlow 对一批外部流水与当前账本状态做只读对账。
// 整份报告对应同一个完整账本状态（与 Submit/Refund 串行在同一把互斥锁上）。
func (l *Ledger) ReconcileFlow(entries []FlowEntry) (*ReconReport, error) {
	if err := l.beginOp(); err != nil {
		return nil, err
	}
	defer l.endOp()
	l.reg.mu.Lock()
	defer l.reg.mu.Unlock()

	st := l.stateView()

	// 结算编号 / 退款编号各自索引：同名编号也不会混为一笔。
	payByID := make(map[string]*Record, len(st.Settlements))
	for i := range st.Settlements {
		payByID[st.Settlements[i].ID] = &st.Settlements[i]
	}
	refundByID := make(map[string]*RefundRecord, len(st.Refunds))
	refundOfPay := make(map[string]*RefundRecord, len(st.Refunds))
	for i := range st.Refunds {
		r := &st.Refunds[i]
		refundByID[r.ID] = r
		refundOfPay[r.SettlementID] = r
	}

	// 标记输入中重复的 (kind,id)：出现多次则整组重复，
	// 无论内容是否相同；全部输入位置附在每条结果上。
	type idUse struct {
		positions []int
	}
	paySeen := map[string]*idUse{}
	refundSeen := map[string]*idUse{}
	for i := range entries {
		e := &entries[i]
		var m map[string]*idUse
		if e.Kind == "payment" {
			m = paySeen
		} else {
			m = refundSeen
		}
		u := m[e.ID]
		if u == nil {
			u = &idUse{}
			m[e.ID] = u
		}
		u.positions = append(u.positions, e.Index)
	}

	report := &ReconReport{
		Results:         make([]ReconResult, 0, len(entries)),
		MissingPayments: []ReconRecordRef{},
		MissingRefunds:  []ReconRecordRef{},
		NetDiff:         []ReconTotalRow{},
		MaxPaymentSeq:   int64(len(st.Settlements)),
		MaxRefundSeq:    int64(len(st.Refunds)),
	}

	ledgerSide := newReconSide()
	flowSide := newReconSide()
	matchedPay := map[string]bool{}
	matchedRefund := map[string]bool{}

	// 逐条结果（保持输入顺序）。
	for i := range entries {
		e := &entries[i]
		res := ReconResult{Index: e.Index, Kind: e.Kind, ID: e.ID}

		var dup map[string]*idUse
		if e.Kind == "payment" {
			dup = paySeen
		} else {
			dup = refundSeen
		}
		if positions := dup[e.ID].positions; len(positions) > 1 {
			res.Status = ReconDuplicate
			// 附上全部输入位置（除自身外的其他位置也在其中，直接给全组位置）。
			res.Diffs = nil
			report.Results = append(report.Results, res)
			// 重复项仍计入流水侧合计，但不占用账本匹配。
			k := balanceKey{e.Account, e.Asset}
			if e.Kind == "payment" {
				flowSide.addCharged(k, e.Charged)
			} else {
				flowSide.addRefund(k, e.Charged)
			}
			// 在结果中暴露整组位置：通过 Diffs 之外的字段不便扩展，
			// 用与条目同级的 positions（见 duplicatePositions 编组）。
			res.duplicatePositions = append([]int(nil), positions...)
			report.Results[len(report.Results)-1] = res
			continue
		}

		if e.Kind == "payment" {
			flowSide.addCharged(balanceKey{e.Account, e.Asset}, e.Charged)
			rec, ok := payByID[e.ID]
			if !ok {
				res.Status = ReconMissingInLedger
			} else {
				matchedPay[e.ID] = true
				res.SettlementID = ""
				if rf := refundOfPay[e.ID]; rf != nil {
					res.RefundID = rf.ID
				}
				diffs := comparePayment(rec, e)
				if len(diffs) == 0 {
					res.Status = ReconMatched
				} else {
					res.Status = ReconFieldMismatch
					res.Diffs = diffs
				}
			}
		} else {
			flowSide.addRefund(balanceKey{e.Account, e.Asset}, e.Charged)
			rec, ok := refundByID[e.ID]
			if !ok {
				res.Status = ReconMissingInLedger
			} else {
				matchedRefund[e.ID] = true
				res.SettlementID = rec.SettlementID
				diffs := compareRefund(rec, e)
				if len(diffs) == 0 {
					res.Status = ReconMatched
				} else {
					res.Status = ReconFieldMismatch
					res.Diffs = diffs
				}
			}
		}
		report.Results = append(report.Results, res)
	}

	// 账本侧合计：所有成功结算与成功退款（含被流水重复引用、账本外流水无法
	// 触及的记录——账本侧恒为完整账本）。
	for i := range st.Settlements {
		r := &st.Settlements[i]
		ledgerSide.addCharged(balanceKey{r.Account, r.Asset}, r.Charged)
	}
	for i := range st.Refunds {
		r := &st.Refunds[i]
		ledgerSide.addRefund(balanceKey{r.Account, r.Asset}, r.Charged)
	}

	// 账本有、但流水没有任何同类型同编号条目的成功记录另列缺失。
	// 重复组不抑制缺失：只有真正唯一出现的编号才标记为已覆盖。
	for i := range st.Settlements {
		r := &st.Settlements[i]
		if matchedPay[r.ID] {
			continue
		}
		if u := paySeen[r.ID]; u != nil && len(u.positions) > 1 {
			// 该编号的流水全部是重复输入：账本记录不列为缺失。
			continue
		}
		ref := paymentRef(r, refundOfPay[r.ID])
		report.MissingPayments = append(report.MissingPayments, ref)
	}
	for i := range st.Refunds {
		r := &st.Refunds[i]
		if matchedRefund[r.ID] {
			continue
		}
		if u := refundSeen[r.ID]; u != nil && len(u.positions) > 1 {
			continue
		}
		report.MissingRefunds = append(report.MissingRefunds, refundRef(r))
	}

	report.Totals = ReconTotals{
		Ledger: buildTotalRows(ledgerSide),
		Flow:   buildTotalRows(flowSide),
	}
	report.NetDiff = buildNetDiff(ledgerSide, flowSide)
	return report, nil
}

// duplicatePositions 保存重复组的全部输入位置；通过自定义 MarshalJSON 输出。
// （字段挂在 ReconResult 上但用独立 JSON 键，避免与 Diffs 语义混淆。）

// comparePayment 比较付款的账户、资产、amount、fee、charged。
func comparePayment(r *Record, e *FlowEntry) []FieldDiff {
	var diffs []FieldDiff
	addStr := func(field, ledger, flow string) {
		if ledger != flow {
			diffs = append(diffs, FieldDiff{Field: field, Ledger: ledger, Flow: flow})
		}
	}
	addInt := func(field string, ledger, flow int64) {
		if ledger != flow {
			diffs = append(diffs, FieldDiff{Field: field, Ledger: fmt.Sprintf("%d", ledger), Flow: fmt.Sprintf("%d", flow)})
		}
	}
	addStr("account", r.Account, e.Account)
	addStr("asset", r.Asset, e.Asset)
	addInt("amount", r.Amount, e.Amount)
	addInt("fee", r.Fee, e.Fee)
	addInt("charged", r.Charged, e.Charged)
	return diffs
}

// compareRefund 比较退款的账户、资产、三个金额及原付款编号。
func compareRefund(r *RefundRecord, e *FlowEntry) []FieldDiff {
	var diffs []FieldDiff
	addStr := func(field, ledger, flow string) {
		if ledger != flow {
			diffs = append(diffs, FieldDiff{Field: field, Ledger: ledger, Flow: flow})
		}
	}
	addInt := func(field string, ledger, flow int64) {
		if ledger != flow {
			diffs = append(diffs, FieldDiff{Field: field, Ledger: fmt.Sprintf("%d", ledger), Flow: fmt.Sprintf("%d", flow)})
		}
	}
	addStr("account", r.Account, e.Account)
	addStr("asset", r.Asset, e.Asset)
	addInt("amount", r.Amount, e.Amount)
	addInt("fee", r.Fee, e.Fee)
	addInt("charged", r.Charged, e.Charged)
	addStr("settlement_id", r.SettlementID, e.SettlementID)
	return diffs
}

func paymentRef(r *Record, rf *RefundRecord) ReconRecordRef {
	ref := ReconRecordRef{
		Kind:    "payment",
		ID:      r.ID,
		Account: r.Account,
		Asset:   r.Asset,
		Amount:  r.Amount,
		Fee:     r.Fee,
		Charged: r.Charged,
		Seq:     r.Seq,
	}
	if rf != nil {
		ref.RefundID = rf.ID
		ref.RefundSeq = rf.Seq
	}
	return ref
}

func refundRef(r *RefundRecord) ReconRecordRef {
	return ReconRecordRef{
		Kind:         "refund",
		ID:           r.ID,
		Account:      r.Account,
		Asset:        r.Asset,
		Amount:       r.Amount,
		Fee:          r.Fee,
		Charged:      r.Charged,
		Seq:          r.Seq,
		SettlementID: r.SettlementID,
	}
}

// buildTotalRows 按账户、资产排序输出单侧汇总；净扣款 = 扣款 - 退款。
func buildTotalRows(side reconSide) []ReconTotalRow {
	keys := make(map[balanceKey]bool, len(side.charged)+len(side.refunded))
	for k := range side.charged {
		keys[k] = true
	}
	for k := range side.refunded {
		keys[k] = true
	}
	out := make([]ReconTotalRow, 0, len(keys))
	for k := range keys {
		charged := new(big.Int)
		if x := side.charged[k]; x != nil {
			charged.Set(x)
		}
		refunded := new(big.Int)
		if x := side.refunded[k]; x != nil {
			refunded.Set(x)
		}
		net := new(big.Int).Sub(charged, refunded)
		out = append(out, ReconTotalRow{
			Account:       k.account,
			Asset:         k.asset,
			ChargedTotal:  charged.String(),
			RefundedTotal: refunded.String(),
			NetCharged:    net.String(),
		})
	}
	sortRows(out)
	return out
}

// buildNetDiff 输出每个组合的“流水净扣款 - 账本净扣款”，
// 任一侧出现过的组合都列出（差额为 0 也保留，便于逐组合核对）。
func buildNetDiff(ledger, flow reconSide) []ReconTotalRow {
	keys := map[balanceKey]bool{}
	for k := range ledger.charged {
		keys[k] = true
	}
	for k := range ledger.refunded {
		keys[k] = true
	}
	for k := range flow.charged {
		keys[k] = true
	}
	for k := range flow.refunded {
		keys[k] = true
	}
	netOf := func(side reconSide, k balanceKey) *big.Int {
		charged := new(big.Int)
		if x := side.charged[k]; x != nil {
			charged.Set(x)
		}
		refunded := new(big.Int)
		if x := side.refunded[k]; x != nil {
			refunded.Set(x)
		}
		return charged.Sub(charged, refunded)
	}
	out := make([]ReconTotalRow, 0, len(keys))
	for k := range keys {
		diff := new(big.Int).Sub(netOf(flow, k), netOf(ledger, k))
		out = append(out, ReconTotalRow{
			Account:    k.account,
			Asset:      k.asset,
			NetCharged: diff.String(),
		})
	}
	sortRows(out)
	return out
}

func sortRows(rows []ReconTotalRow) {
	sort.Slice(rows, func(i, j int) bool {
		if rows[i].Account != rows[j].Account {
			return rows[i].Account < rows[j].Account
		}
		return rows[i].Asset < rows[j].Asset
	})
}

