	before, err := os.ReadFile(ledgerPath)
	if err != nil {
		t.Fatal(err)
	}
	body := `{"entries":[{"kind":"payment","id":"zzz","account":"aa-1","asset":"zzz","amount":1,"fee":0,"charged":1}]}`
	if r := runCLIWith(t, []string{"reconcile", "-l", ledgerPath}, body); r.code != 0 {
